var majorityElement = function(nums) {
    let candidate = 0;
    let count = 0;

    for (const num of nums) {
        // When count drops to 0, pick a new candidate
        if (count === 0) {
            candidate = num;
        }

        // Vote: same as candidate → +1, different → -1
        if (num === candidate) {
            count = count + 1;
        } else {
            count = count - 1;
        }
    }

    return candidate;
};

